import { Flow, FlowObject, wfa, trigger, action } from '@servicenow/sdk/automation'
import { StringColumn, IntegerColumn } from '@servicenow/sdk/core'

/**
 * Test case: Complex object WITHOUT explicit $id and co_type_name
 * Expected behavior:
 * 1. Fluent → XML: Generate deterministic co_type_name as FD<variable_sys_id>
 * 2. XML → Fluent: Should NOT include $id and co_type_name (since they're deterministic)
 */
Flow(
    {
        $id: Now.ID['deterministic_complex_object_flow'],
        name: 'Flow with Deterministic Complex Object',
        runAs: 'user',
        flowVariables: {
            employee: FlowObject({
                fields: {
                    name: StringColumn({
                        label: 'Employee Name',
                    }),
                    age: IntegerColumn({
                        label: 'Employee Age',
                    }),
                    department: StringColumn({
                        label: 'Department',
                    }),
                },
                label: 'Employee',
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['deterministic_trigger'],
        },
        {
            table: 'incident',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['deterministic_log_action'],
            },
            {
                log_level: 'info',
                log_message: wfa.dataPill(_params.flowVariables.employee.name, 'string'),
            }
        )
    }
)
